INSERT INTO `bdt_article` (`article_id`, `title`, `slug`, `excerpt`, `body`, `cover_image`, `category`, `status`, `publish_date`, `is_featured`, `is_pinned`, `created_by`, `updated_by`, `biblio_id`, `library_id`, `meta_description`, `meta_keywords`, `view_count`, `created_at`, `updated_at`) VALUES
(1, 'Festival Baca Desa Teras 2026: Merayakan Literasi Bersama', 'festival-baca-desa-teras-2026', 'Festival Baca Desa Teras kembali hadir tahun ini dengan berbagai kegiatan menarik yang melibatkan seluruh warga desa.', '<p>Festival Baca Desa Teras 2026 akan diselenggarakan pada tanggal 25–27 Juli 2026 di Balai Desa Teras. Festival ini menampilkan berbagai kegiatan seperti pameran buku, lomba membaca, diskusi literasi, dan pertunjukan seni berbasis sastra.</p><p>Acara ini terbuka untuk seluruh masyarakat dan tidak dipungut biaya masuk. Mari bergabung dan rayakan semangat literasi bersama!</p>', '/custom/assets/images/event-workshop.png', 'kegiatan', 'published', '2026-07-15 08:00:00', 1, 0, NULL, NULL, NULL, 1, NULL, NULL, 7, '2026-07-15 12:18:47', '2026-07-15 13:09:41'),
(2, 'Koleksi Baru: 50 Judul Buku Pertanian Modern Hadir di Perpustakaan Utama', 'koleksi-baru-buku-pertanian-modern', 'Perpustakaan Utama Desa menerima donasi 50 judul buku pertanian modern dari Dinas Pertanian Boyolali.', '<p>Kabar baik bagi para petani dan pecinta pertanian di Desa Teras! Perpustakaan Utama Desa kini memiliki koleksi baru berupa 50 judul buku tentang pertanian modern, teknik bercocok tanam ramah lingkungan, dan agribisnis.</p><p>Buku-buku ini merupakan donasi dari Dinas Pertanian Kabupaten Boyolali dan sudah tersedia untuk dipinjam mulai hari ini.</p>', '/custom/assets/images/news-featured.png', 'berita', 'published', '2026-07-10 09:00:00', 0, 0, NULL, NULL, NULL, 1, NULL, NULL, 8, '2026-07-15 12:18:47', '2026-07-15 13:09:41'),
(3, 'Workshop Literasi Digital untuk Ibu-Ibu PKK Desa Teras', 'workshop-literasi-digital-pkk', 'Taman Baca Komunitas mengadakan workshop literasi digital gratis untuk ibu-ibu anggota PKK di Desa Teras.', '<p>Taman Baca Komunitas bekerja sama dengan Pemerintah Desa Teras menyelenggarakan Workshop Literasi Digital yang ditujukan khusus untuk ibu-ibu anggota PKK.</p><p>Workshop ini membahas cara memanfaatkan smartphone untuk kegiatan produktif, menghindari hoaks, dan mengakses layanan perpustakaan digital secara gratis.</p><p>Pendaftaran dapat dilakukan langsung di Taman Baca Komunitas atau melalui WhatsApp di nomor yang tertera.</p>', '/custom/assets/images/event-book-club.png', 'kegiatan', 'published', '2026-07-12 10:00:00', 1, 0, NULL, NULL, NULL, 2, NULL, NULL, 3, '2026-07-15 12:18:47', '2026-07-15 13:09:41'),
(4, 'Pengumuman: Perpustakaan Digital Teras Kini Buka hingga Pukul 20.00', 'pengumuman-perpustakaan-digital-buka-malam', 'Mulai 1 Agustus 2026, Perpustakaan Digital Teras memperpanjang jam layanan hingga pukul 20.00 WIB.', '<p>Demi memberikan layanan yang lebih optimal kepada masyarakat, Perpustakaan Digital Teras mengumumkan perpanjangan jam operasional mulai 1 Agustus 2026.</p><p>Perpustakaan kini melayani pengunjung dari pukul <strong>08.00 hingga 20.00 WIB</strong> pada hari Senin–Jumat, sehingga warga yang bekerja di siang hari tetap dapat mengakses layanan perpustakaan di malam hari.</p>', '/custom/assets/images/news-small.png', 'pengumuman', 'published', '2026-07-13 08:00:00', 0, 0, NULL, NULL, NULL, 3, NULL, NULL, 3, '2026-07-15 12:18:47', '2026-07-15 13:09:41');
