INSERT INTO `bdt_feature` (`feature_id`, `icon`, `title`, `description`, `href`, `status`, `sort_order`) VALUES
(1, '<path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/>', 'Layar Peminjaman', 'Pinjam dan kembalikan buku secara digital tanpa perlu antri. Semua proses cukup lewat smartphone Anda.', '/layanan/peminjaman', 'aktif', 1),
(2, '<rect x=\"2\" y=\"3\" width=\"20\" height=\"14\" rx=\"2\" ry=\"2\"/><line x1=\"8\" y1=\"21\" x2=\"16\" y2=\"21\"/><line x1=\"12\" y1=\"17\" x2=\"12\" y2=\"21\"/>', 'Perpustakaan Digital', 'Akses ribuan koleksi buku, jurnal, dan artikel kapan saja dan di mana saja secara gratis.', '/layanan/digital', 'aktif', 2),
(3, '<path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M23 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/>', 'Acara & Workshop', 'Kegiatan literasi rutin setiap bulan untuk semua kalangan: anak-anak, remaja, hingga orang tua.', '/layanan/acara', 'aktif', 3),
(4, '<path d=\"M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z\"/>', 'Keanggotaan Gratis', 'Daftar menjadi anggota secara gratis dan nikmati seluruh fasilitas perpustakaan tanpa biaya apapun.', '/daftar', 'aktif', 4);
INSERT INTO `bdt_information` (`info_id`, `id_name`, `type`, `title`, `content`, `extra_data`, `status`, `sort_order`) VALUES
(1, NULL, 'faq', 'Bagaimana jika saya terlambat mengembalikan buku?', 'Anda akan dikenakan sanksi berupa denda administratif ringan atau pembatasan peminjaman sementara waktu sesuai tata tertib perpustakaan untuk menjaga sirkulasi buku tetap lancar.', NULL, 'aktif', 1),
(2, NULL, 'faq', 'Apakah warga luar Desa Teras boleh meminjam buku?', 'Tentu saja! Siapa pun boleh membaca di tempat. Untuk peminjaman ke rumah, Anda perlu mendaftar menjadi anggota dengan menyertakan kartu identitas resmi.', NULL, 'aktif', 2),
(3, NULL, 'faq', 'Bisakah saya menyumbangkan buku ke perpustakaan?', 'Sangat bisa! Kami menerima donasi buku layak baca untuk disalurkan ke 6 perpustakaan desa. Silakan hubungi pustakawan kami untuk informasi alur donasi lebih lanjut.', NULL, 'aktif', 3),
(4, NULL, 'faq', 'Apakah ada akses internet/WiFi di area baca?', 'Ya, seluruh perpustakaan desa kami difasilitasi dengan koneksi internet nirkabel (WiFi) gratis untuk menunjang aktivitas belajar dan literasi digital warga.', NULL, 'aktif', 4),
(5, 'peminjaman', 'service', 'Panduan Peminjaman', 'Pelajari langkah mudah meminjam buku favorit Anda. Kami mendukung kemudahan akses literasi untuk seluruh warga.', '{\"points\":[\"Maksimal 3 buku per anggota\",\"Durasi pinjam selama 14 hari\",\"Perpanjangan dapat dilakukan 1x\"],\"action_label\":\"Lihat Detail Alur\",\"action_href\":\"#\"}', 'aktif', 1),
(6, 'keanggotaan', 'service', 'Keanggotaan', 'Menjadi bagian dari komunitas pembaca Desa Teras sangatlah mudah dan gratis.', '{\"action_label\":\"Daftar Sekarang\",\"action_href\":\"#\"}', 'aktif', 2),
(7, NULL, 'download', 'Formulir Pendaftaran', '#', NULL, 'aktif', 1),
(8, NULL, 'download', 'Katalog Buku 2024', '#', NULL, 'aktif', 2);
INSERT INTO `bdt_library` (`library_id`, `slims_location_id`, `slug`, `name`, `tagline`, `badge`, `status`, `address`, `village`, `phone`, `email`, `whatsapp`, `google_maps_url`, `latitude`, `longitude`, `cover_image`, `thumbnail_image`, `total_koleksi`, `total_anggota`, `description`, `sejarah`, `visi`, `misi`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'PU', 'perpustakaan-utama', 'Perpustakaan Utama Desa', 'Pusat Literasi & Pengetahuan Desa Teras', 'Unggulan', 'nonaktif', 'Jl. Raya Teras No. 1, Desa Teras, Boyolali', 'Pusat Desa', '(0276) 321000', 'perpus.utama@teras.desa.id', '6281200001111', 'https://maps.google.com/?q=Teras,Boyolali', NULL, NULL, '/custom/assets/images/library-1.png', '/custom/assets/images/library-1.png', 3200, 580, 'Perpustakaan Utama Desa Teras adalah pusat literasi terbesar di Desa Teras yang menyediakan koleksi buku, media digital, dan berbagai program kegiatan literasi untuk seluruh lapisan masyarakat.', 'Perpustakaan ini didirikan pada tahun 2010 atas inisiatif pemerintah desa dan tokoh masyarakat yang peduli terhadap peningkatan literasi warga desa.', 'Menjadi pusat literasi terdepan yang mendorong masyarakat cerdas, berbudaya, dan berdaya saing.', 'Menyediakan layanan perpustakaan yang berkualitas, aksesibel, dan relevan bagi seluruh warga Desa Teras.', 1, '2026-07-15 12:18:47', '2026-07-15 12:23:59'),
(2, 'TB', 'taman-baca-komunitas', 'Taman Baca Komunitas', 'Ruang Baca yang Nyaman di Tengah Komunitas', 'Unggulan', 'nonaktif', 'Jl. Pendidikan No. 5, RT 02 RW 03, Teras', 'RT 02 RW 03', '(0276) 321001', 'taman.baca@teras.desa.id', '6281200002222', 'https://maps.google.com/?q=Teras,Boyolali', NULL, NULL, '/custom/assets/images/library-2.png', '/custom/assets/images/library-2.png', 1800, 420, 'Taman Baca Komunitas hadir sebagai ruang literasi yang ramah dan terbuka untuk semua usia, dengan suasana yang nyaman dan koleksi yang beragam.', 'Dibangun dari swadaya warga pada tahun 2015, taman baca ini menjadi bukti semangat gotong royong masyarakat Teras dalam memajukan pendidikan.', 'Menjadi ruang komunitas literasi yang inklusif dan berkelanjutan.', 'Menyediakan ruang baca yang nyaman, koleksi yang relevan, dan kegiatan literasi yang melibatkan seluruh komunitas.', 2, '2026-07-15 12:18:47', '2026-07-15 12:23:59'),
(3, 'PD', 'perpustakaan-digital', 'Perpustakaan Digital Teras', 'Koleksi Digital untuk Era Modern', 'Digital', 'nonaktif', 'Jl. Merdeka No. 12, Pusat Desa Teras', 'Pusat Desa', '(0276) 321002', 'perpus.digital@teras.desa.id', '6281200003333', 'https://maps.google.com/?q=Teras,Boyolali', NULL, NULL, '/custom/assets/images/library-3.png', '/custom/assets/images/library-3.png', 2500, 310, 'Perpustakaan Digital Teras menghadirkan pengalaman membaca modern dengan koleksi e-book, audio book, dan akses internet gratis untuk mendukung literasi digital masyarakat desa.', 'Diluncurkan pada tahun 2020 sebagai respons terhadap kebutuhan literasi digital di era pandemi, perpustakaan ini terus berkembang menjadi pusat teknologi literasi desa.', 'Menjadi jembatan antara masyarakat desa dan dunia digital melalui literasi yang inklusif.', 'Menyediakan akses layanan digital yang mudah, terjangkau, dan mendidik bagi seluruh warga.', 3, '2026-07-15 12:18:47', '2026-07-15 12:23:59'),
(4, 'BJS', 'sd-banjarsari', 'SD Banjarsari', 'Koleksi perpustakaan sekolah yang terintegrasi ke portal Baca Di Teras', 'Sekolah Dasar', 'aktif', 'SD Banjarsari, Teras, Boyolali', 'Teras', NULL, NULL, NULL, NULL, NULL, NULL, '/custom/assets/images/library-1.png', '/custom/assets/images/library-1.png', 1870, 53, 'Data koleksi berasal dari migrasi database SLIMS sekolah.', NULL, NULL, NULL, 1, '2026-07-15 12:23:59', '2026-07-16 06:46:32'),
(5, 'SD2', 'sd-negeri-2-teras', 'SD Negeri 2 Teras', 'Koleksi perpustakaan sekolah yang terintegrasi ke portal Baca Di Teras', 'Sekolah Dasar', 'aktif', 'SD Negeri 2 Teras, Boyolali', 'Teras', NULL, NULL, NULL, NULL, NULL, NULL, '/custom/assets/images/library-2.png', '/custom/assets/images/library-2.png', 225, 0, 'Data koleksi berasal dari migrasi database INLIS sekolah.', NULL, NULL, NULL, 2, '2026-07-15 12:23:59', '2026-07-15 13:31:10'),
(6, 'SM1', 'smp-negeri-1-teras', 'SMP Negeri 1 Teras', 'Koleksi perpustakaan sekolah yang terintegrasi ke portal Baca Di Teras', 'Sekolah Menengah', 'aktif', 'SMP Negeri 1 Teras, Boyolali', 'Teras', NULL, NULL, NULL, NULL, NULL, NULL, '/custom/assets/images/library-3.png', '/custom/assets/images/library-3.png', 2978, 951, 'Data koleksi berasal dari migrasi database SLIMS sekolah.', NULL, NULL, NULL, 3, '2026-07-15 12:23:59', '2026-07-16 06:46:32'),
(7, 'SM2', 'smp-negeri-2-teras', 'SMP Negeri 2 Teras', 'Koleksi perpustakaan sekolah yang terintegrasi ke portal Baca Di Teras', 'Sekolah Menengah', 'aktif', 'SMP Negeri 2 Teras, Boyolali', 'Teras', NULL, NULL, NULL, NULL, NULL, NULL, '/custom/assets/images/library-detail-hero.png', '/custom/assets/images/library-detail-hero.png', 115, 575, 'Data koleksi berasal dari migrasi database INLIS sekolah.', NULL, NULL, NULL, 4, '2026-07-15 12:23:59', '2026-07-16 06:46:32'),
(8, 'PDT', 'perpustakaan-desa-teras', 'Perpustakaan Desa Teras', 'Pusat Literasi dan Pembelajaran Masyarakat Desa Teras', 'Perpustakaan Desa', 'aktif', 'Balai Desa Teras, Boyolali', 'Desa Teras', NULL, NULL, NULL, NULL, NULL, NULL, '/custom/assets/images/library-detail-hero.png', '/custom/assets/images/library-detail-hero.png', 0, 0, 'Perpustakaan Desa Teras menyediakan berbagai koleksi bacaan dan layanan literasi untuk mendukung budaya membaca serta pembelajaran sepanjang hayat bagi masyarakat Desa Teras.', NULL, NULL, NULL, 5, '2026-07-19 08:39:26', '2026-07-19 08:39:26'),
(9, 'SD1', 'sd-negeri-1-teras', 'SD Negeri 1 Teras', 'Koleksi perpustakaan sekolah yang terintegrasi ke portal Baca Di Teras', 'Sekolah Dasar', 'aktif', 'SD Negeri 1 Teras, Boyolali', 'Teras', NULL, NULL, NULL, NULL, NULL, NULL, '/custom/assets/images/library-1.png', '/custom/assets/images/library-1.png', 0, 0, 'Data koleksi berasal dari migrasi database perpustakaan sekolah.', NULL, NULL, NULL, 6, '2026-07-19 08:39:26', '2026-07-19 08:39:26');
