INSERT INTO `bdt_village_profile` (`profile_id`, `village_name`, `tagline`, `description`, `sejarah`, `address`, `district`, `regency`, `province`, `phone`, `email`, `whatsapp`, `website`, `google_maps_url`, `latitude`, `longitude`, `logo_path`, `hero_image_path`, `updated_at`) VALUES
(1, 'Desa Teras', 'Portal Literasi Digital Desa Teras', 'Baca Di Teras merupakan portal literasi digital yang lahir dari semangat komunitas Desa Teras, Boyolali. Kami percaya bahwa membaca adalah jendela dunia yang harus bisa diakses oleh semua kalangan, tanpa terkecuali — dari anak-anak hingga orang tua.', 'Baca Di Teras berdiri sejak lebih dari 10 tahun lalu sebagai gerakan literasi grassroots yang digagas oleh para tokoh masyarakat Desa Teras. Berawal dari satu rak buku sederhana di teras rumah, kini telah berkembang menjadi jaringan 6 perpustakaan dengan ribuan koleksi.', 'Jl. Raya Teras, Desa Teras', 'Teras', 'Boyolali', 'Jawa Tengah', '+62 271-781000', 'contact@desateras.id', '+62 812-3456-7890', 'https://desateras.go.id', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3955.034!2d110.648!3d-7.515!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x0!2sTeras%2C+Boyolali!5e0!3m2!1sid!2sid!4v0000000000000', -7.51500000, 110.64800000, NULL, NULL, '2026-07-15 12:18:47');
