(4962, 1, 'Keajaiban Haji dan Umroh :  Mengungkap Kedahsyatan Pesona Kabah dan Tanah suci / Sani Nurlatifah', 'Muhammad Sholikhin', NULL, '9786022411437', 477, '2013', '246 :  ilus ;  21cm', NULL, '200 MUH k', 'id', NULL, 49, NULL, NULL, NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, NULL, '2013-10-07 19:17:13', '2013-10-07 19:17:13', NULL),
(4963, 1, 'Islamic Parenting :  Pendidikan anak diusia emas / Hijrah Saputra', 'M. Fauzi Rachman', NULL, '97897990990685', 477, '2011', '134 ;  21cm', NULL, '200 M.  i', 'id', NULL, 49, NULL, 'Buku ini mengulas tuntas bagaimana mempersiapkan diri kita menjadi orang tua yang mampu mempersiapkan tubuh,jiwa, dan akhlak anak-anak kita untuk menghadapi kehidupan dunia. Tugas ini merupakan kewajiban yang ditekankan agama dan hukum masyarakat. Karena itu orang tua yang tidak memerhatikan anaknya dipandang oleh kebanyakan orang sebagai orang yang tidak bertangungn jawab terhadap amanah Allah dan norma masyarakat', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, NULL, '2013-10-07 19:17:13', '2013-10-07 19:17:13', NULL);
